def rob_ii(nums):
    def rob_line(houses):
        prev2, prev1 = 0, 0
        for value in houses:
            current = max(prev1, prev2 + value)
            prev2 = prev1
            prev1 = current
        return prev1

    n = len(nums)
    if n == 1:
        return nums[0]

    return max(rob_line(nums[:-1]), rob_line(nums[1:]))

